DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260512143635_InsertOnlyTriggers_AuditTables') THEN

    CREATE OR REPLACE FUNCTION enforce_insert_only()
    RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RAISE EXCEPTION
            'INSERT-only table: UPDATE and DELETE are prohibited on % (21 CFR 11.10(e))',
            TG_TABLE_NAME;
        RETURN NULL;
    END;
    $$;

    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260512143635_InsertOnlyTriggers_AuditTables') THEN

    DO $$
    BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public' AND table_name = 'master_data_audit_logs') THEN
            IF NOT EXISTS (SELECT 1 FROM pg_trigger
                           WHERE tgname = 'trg_master_data_audit_logs_insert_only') THEN
                CREATE TRIGGER trg_master_data_audit_logs_insert_only
                BEFORE UPDATE OR DELETE ON master_data_audit_logs
                FOR EACH ROW EXECUTE FUNCTION enforce_insert_only();
            END IF;
        END IF;
    END$$;

    END IF;
END $EF$;

