DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260523120000_PhaseA_SpecificationEngine') THEN
    CREATE TABLE specification_templates (
        "SpecTemplateId" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaterialId" integer NOT NULL,
        "SampleTypeId" integer NOT NULL,
        "Stage" text NOT NULL,
        "TemplateName" character varying(200) NOT NULL,
        "Version" character varying(20) NOT NULL DEFAULT '1.0',
        "Description" character varying(1000),
        "Status" text NOT NULL DEFAULT 'Draft',
        "ApprovedBy" character varying(100),
        "ApprovedAt" timestamptz,
        "ApprovalSignatureId" integer,
        "EffectiveFrom" timestamptz,
        "CreatedBy" character varying(100) NOT NULL,
        "CreatedAt" timestamptz NOT NULL,
        "UpdatedBy" character varying(100),
        "UpdatedAt" timestamptz,
