DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260531132157_Add_DecimalPlaces_And_Retest') THEN

    CREATE OR REPLACE VIEW vw_active_spec_limits AS
    SELECT
        s."SpecLimitId",
        s."ParameterId",
        p."ParameterName",
        p."ParameterCode",
        p."Uom",
        s."MaterialId",
        m."MaterialName",
        s."Stage",
        s."MinValue",
        s."MaxValue",
        s."OotMinValue",
        s."OotMaxValue",
        s."RegulatoryTier",
        s."RegulatoryMin",
        s."RegulatoryMax",
        s."Version",
        s."ApprovedAt",
        s."ApprovedBy"
    FROM spec_limits s
    JOIN test_method_parameters p ON s."ParameterId" = p."ParameterId"
    JOIN materials m              ON s."MaterialId"  = m."MaterialId"
    WHERE s."Status" = 'Approved'
      AND s."IsActive" = TRUE;

    END IF;
END $EF$;

